import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.vOTwFLKw.js";const k=JSON.parse('{"title":"ApiBake OpenAPI to PDF Generator","description":"Convert OpenAPI 3 JSON or YAML specifications into clean PDF API documentation with bookmarks, schema links and customizable colors.","frontmatter":{"title":"ApiBake OpenAPI to PDF Generator","description":"Convert OpenAPI 3 JSON or YAML specifications into clean PDF API documentation with bookmarks, schema links and customizable colors.","permalink":"/apibake/","canonicalUrl":"https://curvednebula.com/apibake/","meta":[{"name":"keywords","content":"ApiBake, OpenAPI to PDF, API documentation generator, OpenAPI PDF, Swagger PDF, OpenAPI CLI"},{"property":"og:title","content":"ApiBake OpenAPI to PDF Generator"},{"property":"og:description","content":"Generate readable PDF API documentation from OpenAPI 3 JSON or YAML files with bookmarks and linked schemas."},{"property":"og:type","content":"website"},{"property":"og:url","content":"https://curvednebula.com/apibake/"}],"aside":false},"headers":[],"relativePath":"apibake/index.md","filePath":"apibake/index.md"}'),o={name:"apibake/index.md"};function s(r,e,p,l,d,c){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="apibake-openapi-to-pdf-generator" tabindex="-1">ApiBake OpenAPI to PDF Generator <a class="header-anchor" href="#apibake-openapi-to-pdf-generator" aria-label="Permalink to &quot;ApiBake OpenAPI to PDF Generator&quot;">​</a></h1><p>ApiBake is a command-line API documentation generator that converts OpenAPI 3 JSON or YAML specifications into a clean, readable PDF document.</p><h2 id="openapi-pdf-documentation-features" tabindex="-1">OpenAPI PDF documentation features <a class="header-anchor" href="#openapi-pdf-documentation-features" aria-label="Permalink to &quot;OpenAPI PDF documentation features&quot;">​</a></h2><ul><li>PDF bookmarks and schema cross-references for quick navigation</li><li>API schemas formatted for easy copying into TypeScript code</li><li>Customizable document colors</li><li>Support for individual OpenAPI files or folders</li><li>OpenAPI 3.0.0 and newer specifications</li></ul><h2 id="install-apibake" tabindex="-1">Install ApiBake <a class="header-anchor" href="#install-apibake" aria-label="Permalink to &quot;Install ApiBake&quot;">​</a></h2><p>ApiBake requires Node.js 16 or newer. Install it globally from npm:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apibake</span></span></code></pre></div><h2 id="convert-openapi-to-pdf" tabindex="-1">Convert OpenAPI to PDF <a class="header-anchor" href="#convert-openapi-to-pdf" aria-label="Permalink to &quot;Convert OpenAPI to PDF&quot;">​</a></h2><p>Pass an OpenAPI JSON file, YAML file, or folder to the command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apibake</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openapi.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">folder-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Run <code>apibake -h</code> to see all available command-line options.</p><h2 id="apibake-links" tabindex="-1">ApiBake links <a class="header-anchor" href="#apibake-links" aria-label="Permalink to &quot;ApiBake links&quot;">​</a></h2><ul><li><a href="https://www.npmjs.com/package/apibake" target="_blank" rel="noreferrer">Install ApiBake from npm</a></li><li><a href="https://github.com/curvednebula/apibake-js" target="_blank" rel="noreferrer">View the ApiBake source code on GitHub</a></li></ul><h2 id="why-generate-api-documentation-as-pdf" tabindex="-1">Why generate API documentation as PDF? <a class="header-anchor" href="#why-generate-api-documentation-as-pdf" aria-label="Permalink to &quot;Why generate API documentation as PDF?&quot;">​</a></h2><p>PDF documentation is convenient for offline reading, review, archiving, and sharing a stable version of an API specification. ApiBake focuses on producing a less cluttered document while preserving useful navigation between endpoints and schemas.</p>',15)])])}const u=a(o,[["render",s]]);export{k as __pageData,u as default};
